  nodes.add instr("PLD", amImplied)  # $C18E59: PLD
  nodes.add instr("RTS", amImplied)  # $C18E5A: RTS
  result = assemble(nodes, 0xC187ED'u32,
                    FlagState(m8: false, x8: false, emulation: false))
